assert.ok(restLink.universalUrl.includes('restaurants/meghana-12345'));
assert.strictEqual(restLink.appScheme, 'swiggy://menu?restaurant_id=12345');

const trackLink = generateOrderTrackingDeepLink({ orderId: 'SWG-9988' });
