        </div>`;
      return;
    }

    // Map: alias (lowercase) -> array of groupJids
    const bindingsByProject = {};
    for (const [groupJid, alias] of Object.entries(groupBindings || {})) {
      if (!alias) continue;
      const lower = alias.toLowerCase();
      if (!bindingsByProject[lower]) {
        bindingsByProject[lower] = [];
