  function renderFriendsList(friends) {
    if (!friendsListContainer) return;
    const friendList = Array.isArray(friends) ? friends : [];
    if (badgeFriendsCount) {
      badgeFriendsCount.textContent = `${friendList.length} REGISTERED`;
